"""Deterministic, escaped HTML view of model audit evidence; no external assets."""
import html
from studio_audit import DIMS

def render_report(report):
 e=lambda v:html.escape(str(v),quote=True)
 rows=report['areas'];origin=report['origin'];summary=report['summary'];all_recs=[(r,x) for r in rows for x in r['judgment']['recommendations']]
 all_recs.sort(key=lambda pair:(pair[1]['priority'],-pair[1]['complexity']))
 def refs(items):return ' · '.join(e(x['path'])+':'+str(x['line'])+('–'+str(x['endLine']) if x.get('endLine',x['line'])!=x['line'] else '') for x in items)
 def average(r):
  values=[x['score'] for x in r['judgment']['scores'].values() if x['score'] is not None]
  return f'{sum(values)/len(values):.1f}' if values else '—'
 matrix=''.join('<tr><th><a href="#'+e(r['area']['id'])+'">'+e(r['area']['title'])+'</a></th>'+''.join('<td class="'+('unknown' if r['judgment']['scores'][d]['score'] is None else 'strong' if r['judgment']['scores'][d]['score']>=7 else 'attention')+'">'+e(r['judgment']['scores'][d]['score'] if r['judgment']['scores'][d]['score'] is not None else '待验证')+'</td>' for d in DIMS)+'<td><b>'+average(r)+'</b></td></tr>' for r in rows)
 modules=[]
 for i,r in enumerate(rows):
  a=r['area'];j=r['judgment'];scores=''.join('<div class="score-row"><span>'+e(label)+'</span><div class="track"><i style="width:'+str((j['scores'][d]['score'] or 0)*10)+'%"></i></div><b>'+e(j['scores'][d]['score'] if j['scores'][d]['score'] is not None else '—')+'</b></div><p class="score-reason">'+e(j['scores'][d]['reason'])+'<small>'+refs(j['scores'][d].get('evidenceRefs',[]))+'</small></p>' for d,label in DIMS.items())
  recs=''.join('<li><span class="priority">'+e(x['priority'])+'</span><div><b>'+e(x['action'])+'</b><p>'+e(x.get('why',''))+'</p><small>复杂度 '+str(x['complexity'])+'/5 · '+refs(x.get('evidenceRefs',[]))+'</small><p class="acceptance">未来验收：'+e(x['acceptance'])+'</p></div></li>' for x in j['recommendations'])
  decisions=''.join('<tr><td>'+e(x['findingId'])+'</td><td>'+e({'accept':'采纳','reject':'驳回','defer':'保留待验证'}[x['decision']])+'</td><td>'+e(x['reason'])+'</td></tr>' for x in j['decisions'])
  modules.append('<section class="module" id="'+e(a['id'])+'"><div class="module-heading"><div><span class="eyebrow">DOMAIN '+str(i+1).zfill(2)+'</span><h2>'+e(a['title'])+'</h2></div><div class="area-score">'+average(r)+'<small>/ 10</small></div></div><p class="lead">'+e(j['summary'])+'</p><p class="meta">'+e(a['primary'])+' → '+e(a['secondary'])+' → '+e(a['primary'])+' · Opus 裁决 · DeepSeek 整理<br>实际载入 '+str(r['coverage']['includedFiles'])+' 个文件 / '+str(r['coverage']['candidateFiles'])+' 个候选文件 · 三轮独立上下文</p><div class="module-grid"><div>'+scores+'</div><div><h3>建议与验证办法</h3><ul class="recommendations">'+(recs or '<li>没有新增重点建议。</li>')+'</ul></div></div><details><summary>展开逐条裁决与审查边界</summary><div class="table-scroll"><table><thead><tr><th>论据</th><th>决定</th><th>理由</th></tr></thead><tbody>'+decisions+'</tbody></table></div><ul>'+''.join('<li>'+e(x)+'</li>' for x in j.get('limitations',[]))+'</ul><p>'+e(r['coverage']['notice'])+'</p></details><a class="text-link" href="reports/'+e(a['id'])+'.md" download>下载本模块完整评价 ↗</a></section>')
 priority=''.join('<tr><td><span class="priority">'+e(x['priority'])+'</span></td><td>'+e(r['area']['title'])+'</td><td>'+e(x['action'])+'</td><td>'+str(x['complexity'])+'/5</td></tr>' for r,x in all_recs)
 replay='http://127.0.0.1:8767/studio?project='+report['projectId']+'&session='+report['sessionId']+'&replay=1'
 body='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>项目 · 架构审查报告</title><link rel="stylesheet" href="reports/report.css"></head><body><header><a class="brand" href="#top"><span>K</span> 项目 <small>ARCHITECTURE REVIEW</small></a><nav><a href="#matrix">评分矩阵</a><a href="#priorities">建议顺序</a><a href="'''+e(replay)+'''">协作回放 ↗</a><a href="reports/audit.json" download>下载结构化证据</a></nav></header><main id="top"><div class="eyebrow">READ-ONLY REVIEW · '''+e(report['generatedAt'])+'''</div><h1>看清架构，<br>再决定下一步。</h1><p class="intro">'''+e(summary['summary'])+'''</p><div class="facts"><div><span>架构范围</span><strong>'''+str(len(rows))+'''<small> 个</small></strong></div><div><span>有限交叉审查</span><strong>3<small> 轮</small></strong></div><div><span>改进建议</span><strong>'''+str(len(all_recs))+'''<small> 项</small></strong></div><div><span>本次源码与部署改动</span><strong>0</strong></div></div><div class="provenance"><b>版本与证据</b><p>'''+e(origin.get('summary',''))+'''</p><p>仓库 '''+e(origin.get('repository',''))+''' · '''+('已核对提交 ' if origin.get('remoteVerified') else '历史提交参考 ')+e(origin.get('commit','待远端核验'))+''' · 部署版本 '''+e(origin.get('deployedIteration','待核验'))+'''</p><small>分数是模型基于已载入证据的审查判断。null 表示证据不足；平均值仅对已评分维度计算，不代表生产认证或性能压测结果。</small></div><section id="matrix"><div class="section-head"><div><span class="eyebrow">01 / SCORECARD</span><h2>七维评分矩阵</h2></div><span class="muted">点击模块进入证据与建议</span></div><div class="table-scroll"><table class="matrix"><thead><tr><th>架构范围</th>'''+''.join('<th>'+e(x)+'</th>' for x in DIMS.values())+'''<th>均分</th></tr></thead><tbody>'''+matrix+'''</tbody></table></div></section><section id="priorities"><span class="eyebrow">02 / NEXT ACTIONS</span><h2>建议执行顺序</h2><p class="muted">按优先级排序，同级按复杂度从高到低；本次只提供建议。</p><div class="table-scroll"><table><thead><tr><th>优先级</th><th>范围</th><th>建议</th><th>复杂度</th></tr></thead><tbody>'''+priority+'''</tbody></table></div></section><div class="section-head"><div><span class="eyebrow">03 / EVIDENCE</span><h2>逐模块审查</h2></div></div>'''+''.join(modules)+'''<section class="closing"><h2>仍需验证</h2><ul>'''+''.join('<li>'+e(x)+'</li>' for x in summary.get('risks',[]))+'''</ul><p>'''+e(report['receiptNotice'])+'''</p><a class="text-link" href="README.md" download>下载 Opus 总报告 ↗</a></section></main><footer>雪站 · 真实模型调用 / 独立上下文 / 只读快照<br>页面由结构化裁决生成，原始评价与调用回执保存在交付文件中。</footer></body></html>'''
 css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:#fafbf9;color:#202d28;font:14px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}a:focus-visible,summary:focus-visible{outline:2px solid #557762;outline-offset:5px}header{position:sticky;top:0;z-index:3;display:flex;justify-content:space-between;align-items:center;padding:19px 5%;background:#ffffffed;backdrop-filter:blur(16px);border-bottom:1px solid #e4e8e1}.brand{font-weight:650;font-size:18px;display:flex;align-items:center;gap:12px}.brand>span{display:grid;place-items:center;width:30px;height:30px;background:#345344;color:white;border-radius:7px}.brand small{font-size:10px;letter-spacing:2px;color:#7c8980;margin-left:8px}nav{display:flex;gap:24px;font-size:12px}main{max-width:1240px;margin:auto;padding:65px 40px}.eyebrow{font-size:10px;font-weight:650;letter-spacing:2.5px;color:#738678}h1{font-size:52px;font-weight:550;line-height:1.2;letter-spacing:-2px;margin:18px 0 24px}.intro{max-width:930px;color:#526157;font-size:16px}.facts{display:grid;grid-template-columns:repeat(4,1fr);margin:38px 0;border-top:1px solid #dce3d9;border-bottom:1px solid #dce3d9;padding:24px 0;gap:24px}.facts>div{border-right:1px solid #dce3d9}.facts>div:last-child{border:0}.facts span{display:block;color:#7c897e;font-size:12px}.facts strong{display:block;font-size:34px;font-weight:550}.facts strong small{font-size:13px;font-weight:400;color:#748176}.provenance{background:#eef2ec;border-left:3px solid #81987d;padding:18px 24px;color:#59665c}.provenance p{margin:5px 0;overflow-wrap:anywhere}.provenance small{color:#7a877b}section{margin-top:64px}h2{font-size:25px;font-weight:550;margin:9px 0 20px}h3{font-size:14px;font-weight:650;margin-top:0}.section-head{display:flex;align-items:center;justify-content:space-between}.muted{color:#89948b;font-size:12px}.table-scroll{overflow:auto;border:1px solid #e1e6de;border-radius:10px;background:white}table{width:100%;border-collapse:collapse;text-align:left}td,th{padding:15px 14px;border-bottom:1px solid #edf0ea;vertical-align:top}thead{background:#f3f5f0;color:#7c887c;font-size:11px}th{font-weight:550;white-space:nowrap}tbody tr:last-child>*{border-bottom:0}.matrix td{text-align:center;white-space:nowrap}.matrix td.strong{color:#3f7154;background:#f5f9f4}.matrix td.attention{color:#9b7548;background:#fcfaf4}.matrix td.unknown{color:#999;font-size:11px}.module{padding-top:28px;border-top:1px solid #cad6c8}.module-heading{display:flex;justify-content:space-between;align-items:center}.area-score{font-size:38px;color:#5c785f;letter-spacing:-1px}.area-score small{font-size:12px;color:#8b948a;margin-left:6px}.lead{font-size:15px;line-height:1.9}.meta{font-size:12px;color:#83907f}.module-grid{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.4fr);gap:44px;margin:28px 0}.score-row{display:grid;grid-template-columns:100px 1fr 25px;gap:12px;align-items:center;font-size:12px}.track{height:5px;background:#e5ece1;border-radius:9px;overflow:hidden}.track i{display:block;height:100%;background:#7b987a;border-radius:9px}.score-reason{font-size:12px;color:#667262;margin:7px 0 20px}.score-reason small{display:block;font-size:10px;color:#98a193;overflow-wrap:anywhere;margin-top:4px}.recommendations{list-style:none;margin:0;padding:0}.recommendations>li{display:flex;gap:14px;border-bottom:1px solid #e4e9df;padding:0 0 17px;margin-bottom:18px}.priority{font:11px/1.5 ui-monospace,monospace;border:1px solid #d7ddd0;border-radius:4px;background:#f1f3ec;color:#6c785d;padding:2px 7px;white-space:nowrap;height:22px}.recommendations b{font-weight:600}.recommendations p{font-size:12px;color:#697461;margin:7px 0}.recommendations small{font-size:10px;color:#97a08f;overflow-wrap:anywhere}.acceptance{background:#f0f3ec;padding:9px 12px}details{border-top:1px solid #e5eadf;padding:14px 0}summary{cursor:pointer;color:#708266;font-size:12px}details table{font-size:12px;margin-top:14px}details p,details li{font-size:12px;color:#7d8875}.text-link{display:inline-block;font-size:12px;color:#53744b;margin-top:14px}.closing{background:#edf2e8;padding:25px 30px;border-radius:12px}.closing p,.closing li{color:#6d7b62;font-size:13px}footer{text-align:center;border-top:1px solid #e0e7da;color:#93a086;padding:30px;font-size:11px}@media(max-width:850px){header{align-items:flex-start;gap:15px;padding:15px 22px}nav{flex-wrap:wrap;gap:9px 15px}.brand small{display:none}main{padding:35px 22px}h1{font-size:39px}.facts{grid-template-columns:1fr 1fr}.facts>div:nth-child(2){border:0}.module-grid{grid-template-columns:1fr;gap:22px}.section-head{display:block}.facts strong{font-size:29px}.module-heading h2{font-size:22px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
 return {'index.html':body.encode(),'reports/report.css':css.encode()}
